        .filter(|e| e.path().is_dir())
        .collect();
    for entry in &entries {
        let toml_path = entry.path().join("agent.toml");
        assert!(
            toml_path.exists(),
            "Directory '{}' has no agent.toml",
            entry.file_name().to_string_lossy()
        );
    }
}

